function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 12) return 'words needs 1 to 12 strings.';
  for (const word of words) {
    if (typeof word !== 'string' || !/^[a-z]{1,20}$/.test(word)) return 'Each word has 1 to 20 lowercase letters.';
  }
  if (new Set(words).size !== words.length) return 'The words must be distinct.';
  for (const a of words) for (const b of words) {
    if (a !== b && a.includes(b)) return `"${b}" is inside "${a}"; no word may contain another.`;
  }
  return null;
}

