function shortestSuperstring(words) {
  const n = words.length;
  const overlap = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) {
        continue;
      }
      for (let k = Math.min(words[i].length, words[j].length) - 1; k > 0; k--) {
        if (words[i].endsWith(words[j].slice(0, k))) {
          overlap[i][j] = k;
          break;
        }
      }
    }
  }

  const full = (1 << n) - 1;
  const dp = Array.from({ length: full + 1 }, () => new Array(n).fill(-1));
  const parent = Array.from({ length: full + 1 }, () => new Array(n).fill(-1));
  for (let i = 0; i < n; i++) {
    dp[1 << i][i] = 0;
  }
  for (let mask = 1; mask <= full; mask++) {
    for (let last = 0; last < n; last++) {
      if (dp[mask][last] < 0) {
        continue;
      }
      for (let next = 0; next < n; next++) {
        if (mask & (1 << next)) {
          continue;
        }
        const grown = mask | (1 << next);
        const saved = dp[mask][last] + overlap[last][next];
        if (saved > dp[grown][next]) {
          dp[grown][next] = saved;
          parent[grown][next] = last;
        }
      }
    }
  }

  let last = 0;
  for (let i = 1; i < n; i++) {
    if (dp[full][i] > dp[full][last]) {
      last = i;
    }
  }
  const order = [];
  let mask = full;
  while (last !== -1) {
    order.push(last);
    const previous = parent[mask][last];
    mask ^= 1 << last;
    last = previous;
  }
  order.reverse();
  let answer = words[order[0]];
  for (let t = 1; t < n; t++) {
    answer += words[order[t]].slice(overlap[order[t - 1]][order[t]]);
  }
  return answer;
}

