function shortestSuperstring(words) {
  // Try every order of the words, joining neighbours with their longest overlap.
  const n = words.length;
  const join = (a, b) => {
    let best = 0;
    for (let k = 1; k < a.length && k < b.length; k++) if (a.substring(a.length - k) === b.substring(0, k)) best = k;
    return best;
  };
  const cut = words.map(a => words.map(b => join(a, b)));
  let bestLength = Infinity, bestOrder = null;
  const order = [], used = new Array(n).fill(false);
  const extend = length => {
    if (length >= bestLength) return;
    if (order.length === n) { bestLength = length; bestOrder = order.slice(); return; }
    for (let w = 0; w < n; w++) {
      if (used[w]) continue;
      const add = order.length ? words[w].length - cut[order[order.length - 1]][w] : words[w].length;
      used[w] = true; order.push(w);
      extend(length + add);
      order.pop(); used[w] = false;
    }
  };
  extend(0);
  let text = words[bestOrder[0]];
  for (let t = 1; t < n; t++) text += words[bestOrder[t]].substring(cut[bestOrder[t - 1]][bestOrder[t]]);
  return text;
}

