function generate(rand, size) {
  const large = size === 'large';
  const want = large ? 12 : 1 + Math.floor(rand() * 6);
  const alphabet = large ? 'abcdefgh'.slice(0, 3 + Math.floor(rand() * 6)) : rand() < 0.5 ? 'ab' : 'abcd';
  const letter = () => alphabet[Math.floor(rand() * alphabet.length)];
  // Cut the words out of one random text so that many of them overlap.
  const base = Array.from({ length: large ? 120 : 14 }, letter).join('');
  const words = [];
  for (let tries = 0; words.length < want && tries < 400; tries++) {
    const length = large ? 8 + Math.floor(rand() * 13) : 1 + Math.floor(rand() * 5);
    const start = Math.floor(rand() * (base.length - length + 1));
    const word = rand() < 0.8 ? base.slice(start, start + length) : Array.from({ length }, letter).join('');
    if (words.some(other => other.includes(word) || word.includes(other))) continue;
    words.push(word);
  }
  return [words];
}
